class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `${this.name} is cast, costing ${this.manaCost} mana.`;
  }
}

class FireballSpell extends Spell {
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    // Redundant re-assignment of properties already set by super()
    this.name = name;
    this.manaCost = manaCost;
    this.damage = damage;
  }

  cast() {
    const descriptionPart1 = `${this.name} is unleashed, dealing ${this.damage} damage.`;
    const descriptionPart2 = `It drains ${this.manaCost} mana from the caster.`;
    return descriptionPart1 + " " + descriptionPart2;
  }
}

// Example Usage (for testing):
// const genericSpell = new Spell("Magic Missile", 10);
// console.log(genericSpell.cast());
// const fireball = new FireballSpell("Fireball", 25, 50);
// console.log(fireball.cast());

